            print(pre, '| SPEC acc', r.get('accessionIdentifier',{}).get('value'), '| coll', r['collection'].get('collectedDateTime'), r['collection'].get('collector',{}).get('display'), '| label', ext(r,'label-name'), ext(r,'label-mrn'), ext(r,'label-dob'), '|', r.get('type',{}).get('text'))
        elif t=='MedicationAdministration':
            print(pre, '|', r['medicationCodeableConcept']['text'], '|', r.get('dosage',{}).get('text'), '| status', r['status'], '| eff', r.get('effectiveDateTime'), '|', (r.get('performer') or [{}])[0].get('actor',{}).get('display'))
            for n in r.get('note',[]): print('        note:', n['text'])
