            for n in r.get('note',[]): print('        note:', n['text'])
        elif t=='DocumentReference':
            print(pre, '| DOC', r['type']['text'], '| date', r.get('date'), '| author', (r.get('author') or [{}])[0].get('display'), ext(r,'author-role'), '| status', r.get('docStatus'))
            print('      TEXT:', r['description'].replace('\n','\n      '))
        elif t=='AllergyIntolerance':
            print(pre, '| ALLERGY', r['code']['text'], [m['text'] for rx in r.get('reaction',[]) for m in rx['manifestation']])
        elif t=='Task':
            print(pre, '| TASK', r['code']['coding'][0]['code'], r['status'], r.get('description'), r.get('focus'))
        else:
            print(pre, json.dumps(r))
    # accessioning entries related to this patient's specimens
