    nm = p['name'][0]['text'].split()
    namematch = ln.replace(',','').replace(' ','').upper()==(nm[-1]+nm[0]).upper()
    if not ok or not namematch:
        print(s['id'],pid,p['name'][0]['text'],p['identifier'][0]['value'],p['birthDate'],'| label',ln,lm,ld, 'mrn/dob_ok' if ok else 'MRN/DOB MISMATCH', 'name_ok' if namematch else 'NAME MISMATCH')
print("=== Accession entry vs specimen label mismatch")
for s in specs.values():
    a=s.get('accessionIdentifier',{}).get('value')
    bs=basics.get(a,[])
    if not bs: print('no accession entry for',a,s['id']); continue
    for b in bs:
        if (ext(b,'patient-mrn'),ext(b,'patient-dob'))!=(ext(s,'label-mrn'),ext(s,'label-dob')) or ext(b,'patient-name')!=ext(s,'label-name'):
            print('MISMATCH acc',a,'spec',s['id'],ext(s,'label-name'),ext(s,'label-mrn'),ext(s,'label-dob'),'| basic',b['id'],ext(b,'patient-name'),ext(b,'patient-mrn'),ext(b,'patient-dob'))
print("=== Observation subject vs specimen subject mismatch")
for o in R.values():
    if o['resourceType']!='Observation': continue
    sp=o.get('specimen')
    if not sp: print('no specimen',o['id']); continue
    sid=sp['reference'].split('/')[-1]
    s=specs.get(sid)
    if s is None: print('missing specimen record',sid,o['id']); continue
    if s['subject']['reference']!=o['subject']['reference']:
        print('SUBJ MISMATCH obs',o['id'],o['subject']['reference'],'spec',sid,s['subject']['reference'])
    # accession match obs vs spec
    oa=(o.get('identifier') or [{}])[0].get('value')
    if oa!=s.get('accessionIdentifier',{}).get('value'):
        print('ACC MISMATCH obs',o['id'],oa,'spec',sid,s.get('accessionIdentifier'))
