pats={r['id']:r for r in R if r['resourceType']=='Patient'}
eps=[r for r in R if r['resourceType']=='EpisodeOfCare']
stage={ 'P09a3361':'latent','P2429873':'ps','P254df41':'latent','P2865e20':'latent','P396c7fe':'ps','P3d6b2a7':'latent','P3e26dc9':'latent','P3f3525d':'latent','P44298b5':'latent','P45d125d':'latent','P5a288b4':'ps','P5e6337c':'latent','P5eba35d':'latent','P7030bbb':'ps','P7174842':'latent','P86f7f3d':'latent','Pa9421d2':'latent','Pb2bdcfd':'latent','Pbdba90b':'latent','Pc5f932c':'latent','Pcad01a5':'ps','Pd7bebc5':'latent','Pe5a8691':'latent','Pe76140d':'latent','Pf01d840':'latent','Pf34bdae':'latent','Pfa3b235':'latent','Pfd11513':'ps','Pff38aca':'latent'}
def d(s): return datetime.date.fromisoformat(s[:10])
EV=datetime.date(2026,9,24)
def addm(dt,m):
    y=dt.year+(dt.month-1+m)//12; mo=(dt.month-1+m)%12+1
    import calendar
    return datetime.date(y,mo,min(dt.day,calendar.monthrange(y,mo)[1]))
for e in sorted(eps,key=lambda x:x['patient']['reference']):
    pid=e['patient']['reference'].split('/')[-1]
    recs=by[pid]
    doses=sorted([r for r in recs if r['resourceType']=='MedicationAdministration' and r['status']=='completed' and 'Bicillin' in r['medicationCodeableConcept']['text']], key=lambda r:r['effectiveDateTime'])
    if not doses:
        print(pid, pats[pid]['name'][0]['text'], 'NO BPG DOSE'); continue
    first=d(doses[0]['effectiveDateTime'])
    months=[6,12] if stage[pid]=='ps' else [6,12,24]
    print(pid, pats[pid]['name'][0]['text'], stage[pid], 'first dose',first)
    rpr=[(d(r['effectiveDateTime']),r['id'],r['status']) for r in recs if r['resourceType']=='Observation' and 'RPR' in r['code']['text']]
    rpr.sort()
    for m in months:
        due=addm(first,m); lo=due-datetime.timedelta(30); hi=due+datetime.timedelta(30)
        hits=[x for x in rpr if lo<=x[0]<=hi]
        print('   ',m,'mo due',due,'window',lo,hi,'closed' if hi<EV else 'OPEN','hits',hits)
